// Diagnostic only. Never execute during timing collection.
import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createHash } from 'node:crypto';
const config = JSON.parse(await readFile(process.argv[2], 'utf8'));
const { importsFor, workload } = await import(config.workloads);
const artifact = config.artifact;
const modules = new Map();
for (const name of Object.keys(artifact.wasm.files)) modules.set(name, new WebAssembly.Module(await readFile(join(artifact.dir, name))));
const imports = artifact.parts.map(importsFor);
const counts = {};
const NativeProxy = globalThis.Proxy;
for (const key of ['Map', 'Proxy', 'Symbol', 'DataView', 'ArrayBuffer', 'Uint8Array', 'Uint16Array', 'Int32Array', 'Float32Array', 'BigInt64Array', 'Float64Array', 'TextEncoder', 'TextDecoder']) {
    const original = globalThis[key]; counts[key] = 0;
    globalThis[key] = new NativeProxy(original, {
        apply(target, receiver, args) { counts[key]++; return Reflect.apply(target, receiver, args); },
        construct(target, args, receiver) { counts[key]++; return Reflect.construct(target, args, receiver); },
    });
}
const binding = await import(pathToFileURL(artifact.bundle).href);
const afterImport = { ...counts };
const instances = artifact.parts.map((id, i) => binding['create' + i](name => {
    assert(modules.has(name), 'unexpected core module request ' + name);
    return modules.get(name);
}, imports[i]));
const afterInstantiate = { ...counts };
for (const [i, instance] of instances.entries()) await workload(artifact.parts[i], instance);
const afterKnownAnswers = { ...counts };
const environment = { node: process.version, flags: process.execArgv, debug: process.env.JCO_DEBUG ?? null };
const source = await readFile(new URL(import.meta.url), 'utf8');
await writeFile(config.output, JSON.stringify({
    schema: 1, checkpoint: config.checkpoint, id: config.id, mode: config.mode,
    beforeTrace: 'core modules compiled, WASI imports constructed and workload helpers loaded',
    exclusions: 'ordinary objects/array literals, function/class identities, Promise internals and native/Wasm allocations are not counted',
    environment, afterImport, afterInstantiate, afterKnownAnswers,
    declaredInitializers: artifact.graph.initializers,
    declaredContexts: artifact.graph.contexts,
    sourceSha256: createHash('sha256').update(source).digest('hex'), source,
}, null, 2) + '\n');

